import { describe, expect, test } from "bun:test";

const projectDirectory = new URL("..", import.meta.url).pathname;

async function runCli(template: string, data: string) {
  const directory = await Bun.$`mktemp -d`.text();
  const templatePath = `${directory.trim()}/template.txt`;
  const dataPath = `${directory.trim()}/data.json`;
  await Promise.all([
    Bun.write(templatePath, template),
    Bun.write(dataPath, data),
  ]);

  const process = Bun.spawn(
    ["bun", "run", "src/cli.ts", templatePath, dataPath],
    { cwd: projectDirectory, stdout: "pipe", stderr: "pipe" },
  );
  const [stdout, stderr, exitCode] = await Promise.all([
    new Response(process.stdout).text(),
    new Response(process.stderr).text(),
    process.exited,
  ]);
  return { stdout, stderr, exitCode };
}

describe("CLI", () => {
  test("writes only rendered text to stdout", async () => {
    const result = await runCli("Hello {{name}}!", JSON.stringify({ name: "Ada" }));
    expect(result).toEqual({ stdout: "Hello Ada!", stderr: "", exitCode: 0 });
  });

  test("reports errors on stderr and exits non-zero", async () => {
    const result = await runCli("ignored", "not json");
    expect(result.stdout).toBe("");
    expect(result.stderr.length).toBeGreaterThan(0);
    expect(result.exitCode).not.toBe(0);
  });
});

