export class TemplateError extends Error {
  readonly line: number;
  readonly column: number;

  constructor(message: string, line: number, column: number) {
    super(`Template error at line ${line}, column ${column}: ${message}`);
    this.name = "TemplateError";
    this.line = line;
    this.column = column;
  }
}

type Location = { line: number; column: number };

type Node =
  | { kind: "text"; value: string }
  | { kind: "value"; path: string; escaped: boolean; location: Location }
  | BlockNode;

type BlockNode = {
  kind: "if" | "each";
  path: string;
  truthy: Node[];
  falsy: Node[];
  location: Location;
};

type Frame = {
  block: BlockNode;
  parent: Node[];
  hasElse: boolean;
};

const PATH_PATTERN = /^(?:@index|[^.\s{}]+(?:\.[^.\s{}]+)*)$/;
const MISSING = Symbol("missing");

function makeLocator(source: string): (offset: number) => Location {
  const lineStarts = [0];
  for (let index = 0; index < source.length; index += 1) {
    if (source.charCodeAt(index) === 10) {
      lineStarts.push(index + 1);
    }
  }

  return (offset: number): Location => {
    let low = 0;
    let high = lineStarts.length;
    while (low + 1 < high) {
      const middle = Math.floor((low + high) / 2);
      if (lineStarts[middle] <= offset) {
        low = middle;
      } else {
        high = middle;
      }
    }
    return { line: low + 1, column: offset - lineStarts[low] + 1 };
  };
}

function fail(message: string, location: Location): never {
  throw new TemplateError(message, location.line, location.column);
}

function checkPath(path: string, location: Location): string {
  if (!PATH_PATTERN.test(path)) {
    fail(path.length === 0 ? "expected a path" : `invalid path \"${path}\"`, location);
  }
  return path;
}

function parse(template: string): Node[] {
  const root: Node[] = [];
  const stack: Frame[] = [];
  const locate = makeLocator(template);
  let output = root;
  let cursor = 0;

  while (cursor < template.length) {
    const opening = template.indexOf("{{", cursor);
    if (opening === -1) {
      output.push({ kind: "text", value: template.slice(cursor) });
      break;
    }

    if (opening > cursor) {
      output.push({ kind: "text", value: template.slice(cursor, opening) });
    }

    const triple = template.startsWith("{{{", opening);
    const terminator = triple ? "}}}" : "}}";
    const contentStart = opening + (triple ? 3 : 2);
    const closing = template.indexOf(terminator, contentStart);
    const location = locate(opening);

    if (closing === -1) {
      fail(`unclosed ${triple ? "triple interpolation" : "tag"}`, location);
    }

    const content = template.slice(contentStart, closing).trim();
    cursor = closing + terminator.length;

    if (triple) {
      output.push({
        kind: "value",
        path: checkPath(content, location),
        escaped: false,
        location,
      });
      continue;
    }

    if (content.startsWith("!")) {
      continue;
    }

    const openBlock = /^#([^\s]+)(?:\s+(.*))?$/.exec(content);
    if (openBlock) {
      const blockKind = openBlock[1];
      if (blockKind !== "if" && blockKind !== "each") {
        fail(`unknown block \"${blockKind}\"`, location);
      }

      const block: BlockNode = {
        kind: blockKind,
        path: checkPath((openBlock[2] ?? "").trim(), location),
        truthy: [],
        falsy: [],
        location,
      };
      output.push(block);
      stack.push({ block, parent: output, hasElse: false });
      output = block.truthy;
      continue;
    }

    if (content.startsWith("#")) {
      fail("malformed block opening", location);
    }

    if (content === "else") {
      const frame = stack.at(-1);
      if (!frame) {
        fail("else outside a block", location);
      }
      if (frame.hasElse) {
        fail(`duplicate else in ${frame.block.kind} block`, location);
      }
      frame.hasElse = true;
      output = frame.block.falsy;
      continue;
    }

    if (content.startsWith("else ")) {
      fail("else tag must not contain an expression", location);
    }

    const closeBlock = /^\/([^\s]+)(?:\s+.*)?$/.exec(content);
    if (closeBlock) {
      const blockKind = closeBlock[1];
      if (blockKind !== "if" && blockKind !== "each") {
        fail(`unknown closing block \"${blockKind}\"`, location);
      }
      if (content !== `/${blockKind}`) {
        fail(`closing ${blockKind} tag must not contain an expression`, location);
      }

      const frame = stack.at(-1);
      if (!frame) {
        fail(`closing ${blockKind} without an open block`, location);
      }
      if (frame.block.kind !== blockKind) {
        fail(`mismatched closing block: expected /${frame.block.kind}, found /${blockKind}`, location);
      }

      stack.pop();
      output = frame.parent;
      continue;
    }

    if (content.startsWith("/")) {
      fail("malformed closing block", location);
    }

    output.push({
      kind: "value",
      path: checkPath(content, location),
      escaped: true,
      location,
    });
  }

  const unclosed = stack.at(-1);
  if (unclosed) {
    fail(`unclosed ${unclosed.block.kind} block`, unclosed.block.location);
  }

  return root;
}

function lookup(value: unknown, segments: string[]): unknown | typeof MISSING {
  let current = value;

  for (const segment of segments) {
    if ((typeof current !== "object" || current === null) && typeof current !== "function") {
      return MISSING;
    }
    if (!Object.prototype.hasOwnProperty.call(current, segment)) {
      return MISSING;
    }
    current = (current as Record<string, unknown>)[segment];
  }

  return current;
}

type RenderContext = {
  root: unknown;
  current: unknown;
  index: number | undefined;
};

function resolve(path: string, context: RenderContext): unknown | typeof MISSING {
  if (path === "this") {
    return context.current;
  }
  if (path === "@index") {
    return context.index === undefined ? MISSING : context.index;
  }

  if (path.startsWith("this.")) {
    return lookup(context.current, path.slice(5).split("."));
  }

  const segments = path.split(".");
  const local = lookup(context.current, segments);
  if (local !== MISSING) {
    return local;
  }
  return context.current === context.root ? MISSING : lookup(context.root, segments);
}

function isTruthy(value: unknown | typeof MISSING): boolean {
  if (value === MISSING || value === null || value === undefined || value === false || value === 0 || value === 0n || value === "") {
    return false;
  }
  return !Array.isArray(value) || value.length > 0;
}

function scalarText(value: unknown | typeof MISSING, path: string, location: Location): string {
  if (value === MISSING || value === null || value === undefined) {
    return "";
  }

  switch (typeof value) {
    case "string":
      return value;
    case "number":
    case "boolean":
    case "bigint":
    case "symbol":
      return String(value);
    default:
      fail(`cannot render \"${path}\" as scalar text (received ${typeof value})`, location);
  }
}

function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (character) => {
    switch (character) {
      case "&": return "&amp;";
      case "<": return "&lt;";
      case ">": return "&gt;";
      case "\"": return "&quot;";
      default: return "&#39;";
    }
  });
}

function renderNodes(nodes: Node[], context: RenderContext): string {
  let result = "";

  for (const node of nodes) {
    if (node.kind === "text") {
      result += node.value;
      continue;
    }

    if (node.kind === "value") {
      const text = scalarText(resolve(node.path, context), node.path, node.location);
      result += node.escaped ? escapeHtml(text) : text;
      continue;
    }

    const value = resolve(node.path, context);
    if (node.kind === "if") {
      result += renderNodes(isTruthy(value) ? node.truthy : node.falsy, context);
      continue;
    }

    if (!Array.isArray(value) || value.length === 0) {
      result += renderNodes(node.falsy, context);
      continue;
    }

    for (let index = 0; index < value.length; index += 1) {
      result += renderNodes(node.truthy, {
        root: context.root,
        current: value[index],
        index,
      });
    }
  }

  return result;
}

/** Render a Mini Template string with values from data. */
export function render(template: string, data: unknown): string {
  const nodes = parse(template);
  return renderNodes(nodes, { root: data, current: data, index: undefined });
}

import { render } from "./engine";

async function main(): Promise<void> {
  const args = Bun.argv.slice(2);
  if (args.length !== 2) {
    throw new Error("Usage: bun run src/cli.ts TEMPLATE_FILE DATA.json");
  }

  const [templatePath, dataPath] = args;
  const [template, json] = await Promise.all([
    Bun.file(templatePath).text(),
    Bun.file(dataPath).text(),
  ]);
  const data: unknown = JSON.parse(json);
  process.stdout.write(render(template, data));
}

try {
  await main();
} catch (error) {
  const message = error instanceof Error ? error.message : String(error);
  console.error(message);
  process.exitCode = 1;
}
# Mini Template

A dependency-free TypeScript template renderer for Bun.

```ts
import { render } from "./src/engine";

render("Hello, {{user.name}}!", { user: { name: "Ada" } });
```

`{{path}}` HTML-escapes interpolated values, while `{{{path}}}` leaves them
unchanged. The renderer also supports nested `if` and `each` blocks, `else`,
comments, `this`, and `@index`:

```handlebars
{{#each users}}
  {{@index}}: {{name}}
{{else}}
  No users
{{/each}}
```

Run the CLI with a UTF-8 template and a JSON data file:

```sh
bun run src/cli.ts template.txt data.json
```

Successful output contains only the rendered text. Syntax, file, JSON, and
rendering errors are written to stderr and result in a non-zero exit code.

Run the self-tests with `bun test`.
import { describe, expect, test } from "bun:test";
import { render, TemplateError } from "../src/engine";

describe("interpolation", () => {
  test("escapes HTML and supports raw values", () => {
    const data = { value: `&<>"'` };
    expect(render("{{value}}|{{{value}}}", data)).toBe("&amp;&lt;&gt;&quot;&#39;|&<>\"'");
  });

  test("resolves nested paths and renders missing values as empty", () => {
    expect(render("{{user.name}}/{{user.missing}}", { user: { name: "Ada" } })).toBe("Ada/");
  });

  test("rejects non-scalar values", () => {
    expect(() => render("x {{user}}", { user: { name: "Ada" } })).toThrow("cannot render \"user\" as scalar text");
  });
});

describe("blocks", () => {
  test("uses the specified truthiness rules", () => {
    for (const value of ["", 0, 0n, false, null, undefined, []]) {
      expect(render("{{#if value}}yes{{else}}no{{/if}}", { value })).toBe("no");
    }
    for (const value of ["0", -1, true, {}, [0]]) {
      expect(render("{{#if value}}yes{{else}}no{{/if}}", { value })).toBe("yes");
    }
  });

  test("iterates with item, index, local paths, root fallback, and nesting", () => {
    const template = "{{#each groups}}[{{name}}:{{#each values}}{{@index}}={{this}}/{{title}};{{else}}empty{{/each}}]{{/each}}";
    const data = {
      title: "root",
      groups: [
        { name: "A", values: ["x", "y"] },
        { name: "B", values: [] },
      ],
    };
    expect(render(template, data)).toBe("[A:0=x/root;1=y/root;][B:empty]");
  });

  test("each else is used for missing and non-array values", () => {
    expect(render("{{#each value}}x{{else}}empty{{/each}}", { value: "no" })).toBe("empty");
    expect(render("{{#each missing}}x{{else}}empty{{/each}}", {})).toBe("empty");
  });

  test("preserves whitespace and removes comments", () => {
    expect(render(" a \n {{! ignored }}\n b ", {})).toBe(" a \n \n b ");
  });
});

describe("syntax errors", () => {
  test.each([
    ["{{#wat x}}{{/wat}}", "unknown block \"wat\""],
    ["{{/if}}", "closing if without an open block"],
    ["{{#if x}}{{/each}}", "expected /if, found /each"],
    ["{{#if x}}{{else}}{{else}}{{/if}}", "duplicate else"],
    ["{{else}}", "else outside a block"],
    ["{{#each xs}}", "unclosed each block"],
    ["{{#}}", "malformed block opening"],
    ["{{/}}", "malformed closing block"],
  ])("reports %s", (template, message) => {
    expect(() => render(template, {})).toThrow(message);
  });

  test("includes line and column", () => {
    try {
      render("first\n  {{else}}", {});
      throw new Error("expected render to throw");
    } catch (error) {
      expect(error).toBeInstanceOf(TemplateError);
      expect((error as Error).message).toContain("line 2, column 3");
    }
  });
});
import { describe, expect, test } from "bun:test";

const projectDirectory = new URL("..", import.meta.url).pathname;

async function runCli(templateName: string, dataName: string) {
  const templatePath = new URL(`fixtures/${templateName}`, import.meta.url).pathname;
  const dataPath = new URL(`fixtures/${dataName}`, import.meta.url).pathname;
  const process = Bun.spawn(
    ["bun", "run", "src/cli.ts", templatePath, dataPath],
    { cwd: projectDirectory, stdout: "pipe", stderr: "pipe" },
  );
  const [stdout, stderr, exitCode] = await Promise.all([
    new Response(process.stdout).text(),
    new Response(process.stderr).text(),
    process.exited,
  ]);
  return { stdout, stderr, exitCode };
}

describe("CLI", () => {
  test("writes only rendered text to stdout", async () => {
    const result = await runCli("greeting.txt", "data.json");
    expect(result).toEqual({ stdout: "Hello Ada!\n", stderr: "", exitCode: 0 });
  });

  test("reports errors on stderr and exits non-zero", async () => {
    const result = await runCli("greeting.txt", "invalid.json");
    expect(result.stdout).toBe("");
    expect(result.stderr.length).toBeGreaterThan(0);
    expect(result.exitCode).not.toBe(0);
  });
});
